import { validateTarotDeck } from '../lib/validateTarotDeck.ts'
import type { Arcana, TarotCard, TarotMeaning, TarotSuit } from '../types/tarot.ts'

function meaning(
  keywords: TarotMeaning['keywords'],
  summary: string,
  description: string,
): TarotMeaning {
  return { keywords, summary, description }
}

function card(
  id: string,
  number: number,
  nameCs: string,
  nameEn: string,
  arcana: Arcana,
  suit: TarotSuit | null,
  upright: TarotMeaning,
  reversed: TarotMeaning,
): TarotCard {
  return { id, number, nameCs, nameEn, arcana, suit, image: `/cards/${id}.jpg`, upright, reversed }
}

